"""Generate a PoC of the target Python code that C# should produce."""

from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
OUT = ROOT / "examples" / "auto_generated_poc.py"

CONTENT = '''#!/usr/bin/env python3
"""Auto-generated by PowerSimBuilder (PoC target format).

This file represents the exact shape that
PythonSimulationMainBuilder.cs should emit.
"""
from __future__ import annotations

import numpy as np
from python_runtime import SimulationData
from python_runtime.components import DigitalInput, DigitalOutput


def main() -> None:
    dt = 0.01
    t_end = 1.0
    sim_data = SimulationData(time_step=dt)

    components = {
        "button": DigitalInput("button"),
        "led": DigitalOutput("led"),
    }

    connections = [
        {"from": "button.outputs.state", "to": "led.inputs.command"},
    ]

    sim_data.set_stimulus(
        "button.inputs.state",
        lambda t: 1 if 0.2 <= t < 0.8 else 0,
    )

    n_steps = int(round(t_end / dt))
    for i in range(n_steps + 1):
        t = i * dt
        sim_data.apply_stimulus(components, t)

        for comp in components.values():
            comp.update(t, dt, sim_data)

        for conn in connections:
            src_id, src_sec, src_port = conn["from"].split(".")
            dst_id, dst_sec, dst_port = conn["to"].split(".")
            components[dst_id].inputs[dst_port] = components[src_id].outputs[src_port]

        sim_data.log(t, components)

    print("simulation done")
    print(f"steps: {len(sim_data.logs)}")
    for entry in sim_data.logs:
        if entry["components"]["led"]["outputs"]["state"] == 1:
            print(f"t={entry['time']:.2f} LED ON")


if __name__ == "__main__":
    main()
'''

OUT.write_text(CONTENT, encoding="utf-8")
print(f"written: {OUT} ({len(CONTENT)} chars)")
